.chat-detail-screen .msg-translation-detached {
  display: flex !important;
  width: fit-content !important;
  max-width: 95% !important;   
  margin-top: -4px !important; 
  z-index: 1 !important; 
}
.chat-detail-screen .msg-bubble-wrapper {
  z-index: 2 !important; 
  position: relative !important;
}
.chat-detail-screen .msg-translation-detached-content {
  background: transparent !important;   
  /* 🌟 翻译颜色改为气泡粉色 */
  color: #c7a2b2 !important; 
  border: none !important;              
  padding: 0 4px !important;            
  font-size: 13px !important;           
  line-height: 1.4 !important;
  opacity: 0.9 !important;             
  text-shadow: none !important; 
  box-shadow: none !important; 
}
.chat-detail-screen .msg-translation-detached-them {
  align-self: flex-start !important;
  margin-left: 20px !important; 
}
.chat-detail-screen .msg-translation-detached-me {
  align-self: flex-end !important;
  margin-right: 20px !important;
} 

/* =======================================
   9️⃣ 思维链定制 (粉色系)
   ======================================= */
.chat-detail-screen {
  --thinking-btn-color: #c7a2b2 !important;
  --thinking-arrow-color: #c7a2b2 !important;
  --thinking-text-color: #c7a2b2 !important;
  --thinking-btn-bg: #FEF8FA !important; 
  --thinking-panel-bg: #FEF8FA !important; 
  --thinking-panel-backdrop: none !important; 
  --thinking-panel-border-left: 2px solid #c7a2b2 !important; 
  --thinking-panel-radius: 12px !important;
}
.chat-detail-screen .nuo-thinking-label { font-size: 0 !important; }
.chat-detail-screen .nuo-thinking-icon { display: none !important; }
.chat-detail-screen .nuo-thinking-label::after {
  content: "對於你而言  我衹是一顆星嗎？" !important;
  color: #c7a2b2 !important; 
  font-size: 12px !important;
  letter-spacing: 0.5px !important; 
}

/* =======================================
   💸 🔟 QQ 写实版转账卡片 
   ======================================= */
:root {
  --transfer-icon-bg: transparent !important;
  --transfer-me-icon-bg: transparent !important;
  --transfer-them-icon-bg: transparent !important;
  --transfer-success-icon-bg: transparent !important;
  --transfer-rejected-icon-bg: transparent !important;
  --transfer-expired-icon-bg: transparent !important;
  --transfer-card-border: none !important;
  --transfer-me-card-border: none !important;
  --transfer-them-card-border: none !important;
}

.chat-detail-screen .msg-transfer-card {
  width: 220px !important;
  height: 85px !important;
  background-color: #1BA3FF !important; 
  border-radius: 12px !important;        
  position: relative !important;
  padding: 0 !important; 
  overflow: hidden !important; 
  display: block !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}
.chat-detail-screen .msg-transfer-card.msg-transfer-success {
  background-color: #7BBEFF !important; 
}
.chat-detail-screen .msg-transfer-card.msg-transfer-rejected,
.chat-detail-screen .msg-transfer-card.msg-transfer-expired-card {
  background-color: #D4D4D4 !important; 
}

.chat-detail-screen .msg-transfer-card::before {
  content: "";
  position: absolute;
  bottom: 24px; left: 12px; right: 12px; height: 1px;
  background-color: rgba(255, 255, 255, 0.25) !important;
  transform: scaleY(0.5); 
  z-index: 1;
}

.chat-detail-screen .msg-transfer-card svg,
.chat-detail-screen .msg-transfer-divider {
  display: none !important;
}

.chat-detail-screen .msg-transfer-card::after {
  content: "";
  position: absolute;
  top: 12px; left: 12px; width: 38px; height: 38px;
  background-image: url('https://i.imgant.com/v2/r7FlGkx.png');
  background-size: 100% 100%; background-repeat: no-repeat; z-index: 2;
}

.chat-detail-screen .msg-transfer-amount {
  position: absolute !important;
  top: 14px !important;
  left: 60px !important;      
  z-index: 2 !important;
  display: flex !important;           
  flex-direction: row !important;
  align-items: baseline !important;   
  white-space: nowrap !important;     
}
.chat-detail-screen .msg-transfer-amount,
.chat-detail-screen .msg-transfer-amount * {
  color: #ffffff !important;  
  -webkit-text-fill-color: #ffffff !important; 
  font-size: 16px !important;
  font-weight: bold !important;
  line-height: 1 !important;
  background: transparent !important; 
}

.chat-detail-screen .msg-transfer-label {
  position: absolute !important; 
  top: 36px !important;            
  left: 60px !important;
  z-index: 2 !important; 
  font-size: 0 !important; 
}
.chat-detail-screen .msg-transfer-label::after {
  content: "眼泪好烫 爱也是这个温度吗" !important;
  color: rgba(255, 255, 255, 0.8) !important; 
  -webkit-text-fill-color: rgba(255, 255, 255, 0.8) !important; 
  font-size: 12px !important; 
}

.chat-detail-screen .msg-transfer-status-text {
  position: absolute !important; bottom: 5px !important; left: 14px !important; font-size: 0 !important; z-index: 2 !important; margin: 0 !important; padding: 0 !important; background: transparent !important;
}
.chat-detail-screen .msg-transfer-status-text::after {
  content: "转账" !important; font-size: 11px !important; color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; 
}

.chat-detail-screen .msg-transfer-subtitle,
.chat-detail-screen .msg-transfer-card [class*="expire" i],
.chat-detail-screen .msg-transfer-card [class*="time" i],
.chat-detail-screen .msg-transfer-card [class*="count" i], 
.chat-detail-screen .msg-transfer-card [class*="timer" i], 
.chat-detail-screen .msg-transfer-card [class*="note" i],  
.chat-detail-screen .msg-transfer-card [class*="dot" i],
.chat-detail-screen .msg-transfer-card [class*="unread" i],
.chat-detail-screen .msg-transfer-status-text *,
.chat-detail-screen .msg-transfer-label * {
  display: none !important; 
}

.chat-detail-screen .msg-transfer-card *:not(.msg-transfer-amount):not(.msg-transfer-amount *):not(.msg-transfer-label):not(.msg-transfer-status-text) {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  font-size: 0 !important;
  letter-spacing: -999px !important;
}

.chat-detail-screen .msg-transfer-card {
  max-height: 85px !important;
  min-height: 85px !important;
}

custom.css:
.page { position: absolute; inset: 0; color: #fff; font-family: -apple-system, "PingFang SC", sans-serif; }
.bg { position: absolute; inset: 0; background: {{accent}} url("{{portrait}}") center top / cover no-repeat; }
.bg::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,.4), rgba(0,0,0,0) 30%, rgba(0,0,0,0) 55%, rgba(0,0,0,.6)); }
.clock { position: absolute; left: 24px; top: calc(var(--safe-top, 44px) + 16px); }
.clock b { display: block; font-size: 64px; line-height: 1; letter-spacing: -1px; }
.clock small { display: block; margin-top: 6px; font-size: 14px; opacity: .9; }
.card { position: absolute; left: 20px; right: 20px; bottom: 124px; padding: 12px 16px; border-radius: 16px; background: rgba(255,255,255,.92); color: #333; }
.card em { font-style: normal; font-size: 13px; font-weight: 700; color: {{accent}}; }
.card p { margin: 4px 0 0; font-size: 15px; line-height: 1.5; }
.apps { position: absolute; left: 16px; right: 16px; bottom: 44px; display: flex; gap: 10px; }
.app { flex: 1; padding: 14px 0; border-radius: 16px; text-align: center; font-size: 13px; font-weight: 700; background: rgba(0,0,0,.35); border: 1px solid rgba(255,255,255,.35); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.app.start { background: {{accent}}; border-color: transparent; }
@keyframes rise { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
@keyframes shine { 0% { background-position: 150% 0; } 60%, 100% { background-position: -50% 0; } }
html.tp-fx:not(.tp-enter) .clock, html.tp-fx:not(.tp-enter) .card, html.tp-fx:not(.tp-enter) .apps { opacity: 0; }
.tp-enter .clock { animation: rise .8s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .card { animation: rise .8s .15s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .apps { animation: rise .8s .3s cubic-bezier(.2,.8,.2,1) both; }
.app.start { background-image: linear-gradient(110deg, transparent 35%, rgba(255,255,255,.55) 50%, transparent 65%); background-size: 250% 100%; background-repeat: no-repeat; animation: shine 3s ease-in-out infinite; }

