                    <i class="fas fa-sun icon-sun"></i>
                </span>
            </div>

            <div class="tarot-title-box">
                <div class="tarot-title">$1</div>
                <div class="tarot-subtitle">Astral Resonance</div>
            </div>

            <div class="tarot-info-grid">
