    <style>
        @import url('https://fonts.googleapis.com/css2?family=Cinzel+Decorative&family=Great+Vibes&family=Noto+Serif+SC:wght@300;400&display=swap');

        /* --- 动画定义区 --- */
        @keyframes ethereal-fade {
            0% { opacity: 0; transform: translateY(15px); filter: blur(8px); }
            100% { opacity: 1; transform: translateY(0); filter: blur(0); }
        }
        @keyframes spin-cw {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }
        @keyframes spin-ccw {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(-360deg); }
        }
        @keyframes star-pulse {
            0%, 100% { opacity: 0.3; box-shadow: 0 0 2px var(--t-secondary); transform: scale(0.8); }
            50% { opacity: 1; box-shadow: 0 0 8px var(--t-primary); transform: scale(1.2); }
        }
        @keyframes star-twinkle {
            0% { opacity: 0.15; transform: translate(-50%, -50%) scale(0.7); }
            100% { opacity: 0.9; transform: translate(-50%, -50%) scale(1.3); box-shadow: 0 0 6px var(--t-primary); }
        }
        @keyframes axis-grow-y {
            0% { top: 50%; bottom: 50%; opacity: 0; }
            100% { top: 0; bottom: 0; opacity: 1; }
        }
        @keyframes axis-grow-x {
            0% { left: 50%; right: 50%; opacity: 0; }
            100% { left: 10%; right: 10%; opacity: 1; }
        }

        /* 作用域限制，避免污染全局 */
        .tarot-wrapper {
            --t-rgb: 255, 255, 255;
            --t-primary: rgba(var(--t-rgb), 0.85);
            --t-secondary: rgba(var(--t-rgb), 0.6);
            --t-tertiary: rgba(var(--t-rgb), 0.4);
            --t-line-strong: rgba(var(--t-rgb), 0.3);
            --t-line-weak: rgba(var(--t-rgb), 0.12);
            --t-line-faint: rgba(var(--t-rgb), 0.06);

            font-family: "NanoOldSong-A", serif;
            position: relative;
            width: 100%;
            max-width: 600px;
            margin: 20px auto 30px;
            padding: 30px 0;
            background: transparent;
            color: var(--t-primary);
            overflow: hidden;
