        /* 静态主坐标轴 */
        .tarot-axis-y {
            position: absolute;
            left: 50%;
            width: 1px;
            background: var(--t-line-weak);
            transform: translateX(-50%);
            z-index: 0;
            animation: axis-grow-y 1.2s ease-out forwards;
        }
        .tarot-axis-x {
            position: absolute;
            top: 85px;
            height: 1px;
            background: var(--t-line-strong);
            z-index: 0;
            animation: axis-grow-x 1.2s ease-out forwards;
        }

        /* --- 动态星盘系统 (Astrolabe) --- */
        .tarot-astrolabe {
            position: absolute;
            top: 85px; /* 定位于十字轴交点 */
            left: 50%;
            width: 0;
            height: 0;
            z-index: 0;
            pointer-events: none;
        }

        /* 中心发光菱形枢纽 */
        .astro-core {
            position: absolute;
            top: -4px; left: -4px;
            width: 8px; height: 8px;
            border: 1px solid var(--t-primary);
            transform: rotate(45deg);
            box-shadow: 0 0 6px var(--t-secondary);
        }

        /* 外层实线大星轨 */
        .astro-orbit-outer {
            position: absolute;
            top: -200px; left: -200px;
            width: 400px; height: 400px;
            border: 1px solid var(--t-line-weak);
            border-radius: 50%;
            animation: spin-cw 150s linear infinite;
