        .cb-s4 { top: 100px; left: 60px; animation-delay: 1.7s; }
        .cb-l1 { top: 60px; left: 80px; width: 53.8px; transform: rotate(21.8deg); }
        .cb-l2 { top: 80px; left: 130px; width: 53.8px; transform: rotate(111.8deg); }
